ground_truth.generate:
set -e; d=$(mktemp -d); cat > "$d/gen.c" <<'EOF'
/* the write half of tests/lossy_comp_test.c lcomp_test_short("g721.au", SF_ENDIAN_LITTLE | SF_FORMAT_AU | SF_FORMAT_G721_32, 1, 0.7) (test au_g721) */
#include <math.h>
#include <string.h>
#include <sndfile.h>
#define BUFFER_SIZE (1 << 14)
#define SAMPLE_RATE 11025
#define DECAY_COUNT 1000
static const char *long_comment =
	"This is really quite a long comment. It is designed to be long enough "
	"to screw up the encoders and decoders if the file container format does "
	"not handle things correctly. If everything is working correctly, the "
	"decoder will only decode the actual audio data, and not this string at "
	"the end of the file." ;
static double orig_d [BUFFER_SIZE + 1] ;
static short orig [BUFFER_SIZE + 1] ;
int main (int argc, char *argv [])
{	SF_INFO sfinfo ;
	SNDFILE *file ;
	int k, ramplen = DECAY_COUNT ;
	sf_count_t datalen = BUFFER_SIZE / 1 ;
	double amp = 0.0, scale = 32000.0 ;
	if (argc != 2) return 2 ;
	for (k = 0 ; k < datalen ; k++)	/* gen_signal_double (orig, 32000.0, 1, datalen) */
	{	if (k <= ramplen)
			amp = scale * k / ((double) ramplen) ;
		else if (k > datalen - ramplen)
			amp = scale * (datalen - k) / ((double) ramplen) ;
		orig_d [k] = amp * (0.4 * sin (33.3 * 2.0 * M_PI * ((double) (k+1)) / ((double) SAMPLE_RATE))
						+ 0.3 * cos (201.1 * 2.0 * M_PI * ((double) (k+1)) / ((double) SAMPLE_RATE))) ;
		} ;
	for (k = 0 ; k < datalen ; k++)
		orig [k] = (short) (orig_d [k]) ;
	memset (&sfinfo, 0, sizeof (sfinfo)) ;
	sfinfo.samplerate = SAMPLE_RATE ;
	sfinfo.frames = 123456789 ;
	sfinfo.channels = 1 ;
	sfinfo.format = SF_ENDIAN_LITTLE | SF_FORMAT_AU | SF_FORMAT_G721_32 ;
	if ((file = sf_open (argv [1], SFM_WRITE, &sfinfo)) == NULL) return 1 ;
	if (sf_writef_short (file, orig, datalen) != datalen) return 1 ;
	sf_set_string (file, SF_STR_COMMENT, long_comment) ;
	sf_close (file) ;
	return 0 ;
}
EOF
clang -fsanitize=address -I/src/libsndfile/include "$d/gen.c" /src/libsndfile/src/.libs/libsndfile.a -lm -o "$d/gen"
ASAN_OPTIONS=detect_leaks=0 "$d/gen" /cf_gt_out/lct_g721.au
rm -rf "$d"
